<?php require_once '../includes/config.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';if($a==='add'){$st=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$st->execute([post_str('name'),post_str('description')]);flash('success','Category added.');}elseif($a==='toggle'){$pdo->prepare('UPDATE categories SET status=1-status WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Category status updated.');}elseif($a==='delete'){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Category deleted.');}redirect('categories.php');}$rows=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$title='Categories';require '../includes/header.php';?><div class="d-flex justify-content-between"><h1 class="section-title">Categories</h1><button class="btn btn-purple" data-bs-toggle="modal" data-bs-target="#add">Add Category</button></div><div class="panel overflow-hidden mt-3"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Description</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['description'])?></td><td><?=$r['status']?'Active':'Inactive'?></td><td><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-purple">Toggle</button></form><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete" data-confirm="Delete this category? Products using it may prevent deletion." class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal fade" id="add"><div class="modal-dialog"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5>Add Category</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control mb-2" name="name" placeholder="Category name" required><textarea class="form-control" name="description" placeholder="Description"></textarea></div><div class="modal-footer"><button class="btn btn-purple">Create</button></div></form></div></div></div><?php require '../includes/footer.php';?>
